import itertools
def val(a,b,c,d,e,f,g):
    return a+b/c-d/e+f*g
base=[19,125,25,100,5,4,3]
def sw(x,y):
    l=[y if v==x else x if v==y else v for v in base]
    return val(*l)
o={'A':(125,100),'B':(25,5),'C':(19,4),'D':(4,5)}
ok=[k for k,v in o.items() if abs(sw(*v)-52)<1e-9]
