import itertools
# elements types: subsets of {M,C,T,L}; enumerate models with few individuals
types=[frozenset(s) for r in range(5) for s in itertools.combinations('MCTL',r)]
valid=[t for t in types if not ('M' in t and 'C' in t)]
def some(m,a,b): return any(a in t and b in t for t in m)
c1=c2=True
for n in range(1,5):
    for m in itertools.combinations_with_replacement(valid,n):
        if some(m,'C','T') and some(m,'T','L'):
            if not some(m,'C','L'): c1=False
            # II: no tablet is a medicine
            if some(m,'T','M'): c2=False
assert c1 is False and c2 is False
o={'A':(False,False),'B':(False,True),'C':(True,True),'D':(True,False)}
assert o['A']==(c1,c2)
assert all(v!=(c1,c2) for k,v in o.items() if k!='A')

import itertools
types=[frozenset(s) for r in range(5) for s in itertools.combinations('BDSR',r) ]
# B beach, D desert, S sand, R rocky(mountain rocky irrelevant, R = rocky)
valid=[t for t in types if not ('B' in t and 'S' not in t)]
def some(m,a,b): return any(a in t and b in t for t in m)
c1=c2=True
for n in range(1,5):
    for m in itertools.combinations_with_replacement(valid,n):
        if some(m,'D','S'):
            if not some(m,'B','D'): c1=False
            if not some(m,'S','R'): c2=False
assert (c1,c2)==(False,False)
o={'A':(False,False),'B':(True,True),'C':(True,False),'D':(False,True)}
assert o['A']==(c1,c2)
assert all(v!=(c1,c2) for k,v in o.items() if k!='A')

t='QUA_TO_ANT_UAN_KU_NT'
o={'A':'NUTMA','B':'NUMTA','C':'NULTA','D':'NUTAM'}
